public class Waehrungsrechner {

    public static double euroInDollar(double euro) {
        return euro * 1.5;
    }

    public static double dollarInEuro(double dollar) {
        return dollar / 1.5;
    }

    public static void main(String[] args) {
        System.out.println("100.0 Euro = " + euroInDollar(100.0) + " Dollar");
        System.out.println(dollarInEuro(75.0) + " Euro = 50.0 Dollar");
    }
}
